function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
s1 = 68.1250*10^-9 ;
s2 = -56.4512*10^-6;
s3 = 32.5553*10^-3 ;
s4 = -4.3529*10^-9 ;
s5 = 3.3216*10^-6  ;
s6 = -2.7141*10^-3 ;
z1 = 7.8407*10^-6  ;
z2 =  -4.0507*10^-3;
z3 = 1.0585        ;
z4 =  1.2318*10^-9 ;
z5 = -9.7660*10^-6 ;
z6 = -1.1677*10^-3 ;
w1 = -0.0769*10^-6 ;
w2 =  -0.0035*10^-3;
w3 = 0.0349*10^-3  ;
w4 =  0.9961       ;

y(1)=( ( s1*x(2)^2 + s2*x(2) + s3 )*exp( (s4*x(2)^2 + s5*x(2) + s6) * x(1))  );
y(2)=( ( z1*x(2)^2 + z2*x(2) + z3 )*exp( (z4*x(2)^2 + z5*x(2) + z6) * x(1))  );
y(3)=( ( w1*x(2) + w2 )*x(1) + (w3*x(2)+w4)                                  );

dx(1)=(( x(1)/x(3) )*( y(1)*(y(3) - u(1) ) ))*tal;
dx(2)=(( x(2)/x(3) )*( y(1)*(y(2) - u(1) ) ))*tal;
dx(3)=( y(1)*(u(1) - 1)                     )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
